<link rel="stylesheet" href="/assets/account.css?v=20261104r2">
<style>.nx-chat-rooms{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0}.nx-chat-rooms a{padding:10px 15px;border:1px solid color-mix(in srgb,var(--text-color) 30%,transparent);border-radius:9px;color:var(--text-color);text-decoration:none;min-height:44px}.nx-chat-rooms a[aria-current]{border-color:var(--primary);background:var(--card-bg)}.nx-chat-history{max-height:450px;min-height:160px;overflow:auto;overflow-wrap:anywhere;line-height:1.8}.nx-chat-history p{border-bottom:1px solid color-mix(in srgb,var(--text-color) 15%,transparent);padding:12px 0}.nx-chat-history strong{color:var(--primary)}.nx-chat-compose{display:grid;gap:14px;margin-top:24px}.nx-chat-compose textarea{display:block;box-sizing:border-box;width:100%;padding:15px;background:var(--bg-color);color:var(--text-color);border:1px solid color-mix(in srgb,var(--text-color) 35%,transparent);border-radius:9px;font-size:16px;line-height:1.6;font-family:inherit;resize:vertical}.nx-chat-compose button{justify-self:start}.nx-chat-notice{border-left:3px solid var(--primary);padding:12px;margin:15px 0}</style>
<section class="nx-account-page" data-community-chat>
<div class="nx-account-heading"><div><p class="nx-account-eyebrow">GOLDENSITE / COMUNIDAD</p><h1>Chat de la comunidad</h1><p>Conversaciones entre usuarios en las salas autorizadas de Live Chat.</p></div></div>
<nav class="nx-chat-rooms" aria-label="Salas del chat"><?php foreach ($rooms as $room): ?><a href="/chat?channel=<?= rawurlencode($room['slug']) ?>" <?= $room['slug']===$channel?'aria-current="page"':'' ?> data-nx-content><?= $e($room['name']) ?></a><?php endforeach ?></nav>
<?php if ($notice): ?><p class="nx-chat-notice" role="status"><?= $e($notice) ?></p><?php endif ?>
<section class="nx-account-card"><h2 data-nx-content><?= $e($currentRoom['name']??$channel) ?></h2><div id="chat-messages" class="nx-chat-history" aria-live="polite" aria-label="Mensajes de la sala"><?php if (!$messages): ?><p>Aún no hay mensajes en esta sala.</p><?php endif ?><?php foreach ($messages as $message): ?><p data-nx-content><strong><?= $e($message['sender_name']) ?>:</strong> <?= $e($message['message']) ?></p><?php endforeach ?></div>
<form method="post" action="/chat?channel=<?= rawurlencode($channel) ?>" class="nx-chat-compose"><input type="hidden" name="csrf_token" value="<?= $e(\App\Core\Csrf::generate()) ?>"><label>Mensaje<textarea name="message" maxlength="2000" required rows="3" placeholder="Escribe un mensaje para esta sala"></textarea></label><button class="nx-account-action" type="submit">Enviar mensaje</button></form></section>
</section>
<script>
setInterval(async()=>{if(document.hidden)return;try{const r=await fetch('/api/chat/messages?channel='+encodeURIComponent(<?= json_encode($channel, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>));if(!r.ok)return;const data=await r.json();if(!data.success)return;const box=document.getElementById('chat-messages');const signature=JSON.stringify(data.messages);if(box.dataset.last===signature)return;box.dataset.last=signature;box.replaceChildren();if(!data.messages.length){const p=document.createElement('p');p.textContent='Aún no hay mensajes en esta sala.';box.append(p);}for(const m of data.messages){const p=document.createElement('p');p.setAttribute('data-nx-content','');const name=document.createElement('strong');name.textContent=m.sender_name+': ';p.append(name,document.createTextNode(m.message));box.append(p);}}catch{}},10000);
</script>
